/**
 * Repro test generated by Session Recorder from a recorded browser session.
 *
 * It replays the recorded steps with Playwright and checks whether the errors
 * the recording captured happen again:
 *
 *   REPRODUCED      fails: a recorded error happened again. The first such run
 *                   writes .repro-baseline.json next to this file.
 *   INCONCLUSIVE    fails: the replay did not reach the bug, so it shows nothing
 *                   about a fix.
 *   NOT REPRODUCED  passes: an earlier run reproduced the bug against the same
 *                   target, every step ran, each failing request was sent again
 *                   with the recorded fields and succeeded, nothing was left
 *                   pending, and no recorded error happened again. This is not
 *                   proof that the bug is fixed.
 *
 * Run it on the unfixed code first. Environment variables:
 *
 *   BASE_URL              origin to replay against (default: the recorded origin)
 *   REPRO_ALLOW_REMOTE=1  allow a non-local target, navigation to non-local
 *                         hosts and requests that change data there
 *   REPRO_STORAGE_STATE   Playwright storage-state file to start signed in
 *   REPRO_INPUT_<n>       values for redacted fields (see PLAN.steps)
 *   REPRO_WAIT_MS         how long to wait for pending requests (default 30000)
 *   REPRO_IGNORE_PENDING  regular expression of paths not to wait for (long polls)
 *
 * PLAN below is data recorded from the page. The code in this file does not
 * change between recordings.
 */
import { test, type Locator, type Page, type Request } from '@playwright/test';

// --- Plan types --------------------------------------------------------------

export interface Candidate {
  by: 'testid' | 'css' | 'role' | 'label' | 'name' | 'text';
  value: string;
  role?: string;
}

export interface Target {
  label: string;
  candidates: Candidate[];
}

export type Step =
  | { kind: 'goto'; url: string; at: number }
  | { kind: 'reload'; at: number }
  | {
      kind: 'click';
      target: Target;
      button?: 'left' | 'right' | 'middle';
      modifiers?: ('Alt' | 'Control' | 'Meta' | 'Shift')[];
      at: number;
    }
  | { kind: 'fill'; target: Target; value?: string; env?: string; at: number }
  | { kind: 'select'; target: Target; value: string; at: number }
  | { kind: 'upload'; target: Target; file: string; at: number }
  | { kind: 'press'; key: string; at: number };

export type Signal =
  | {
      kind: 'exception' | 'console';
      text: string;
      /** Regular expressions for the text around logged objects, found in order. */
      parts: string[];
      at: number;
      /** Index of the step this signal followed in the recording. */
      afterStep: number;
    }
  | {
      kind: 'request';
      method: string;
      path: string;
      pathPattern: string;
      status: number | 'failed';
      /** Body fields that had a value in the recorded request. */
      fields: string[];
      /** Base content type of the recorded failing response. */
      mime?: string;
      at: number;
      afterStep: number;
    };

export interface Plan {
  /** Identifies this plan in .repro-baseline.json. */
  id: string;
  version: 1;
  title: string;
  recordedOrigin: string;
  steps: Step[];
  signals: Signal[];
  settleMs: number;
  /** Reasons this replay cannot show that the bug is gone. */
  blockers: string[];
  /** Set when there is nothing to check; the test is marked fixme. */
  fixme?: string;
}

const PLAN: Plan = /*@repro-plan*/ ({} as Plan);

// --- Settings ----------------------------------------------------------------

/** Changes when the verdict rules change, so an older baseline stops counting. */
const RUNNER_VERSION = 4;
const ENV: Record<string, string | undefined> =
  (globalThis as { process?: { env?: Record<string, string | undefined> } }).process
    ?.env ?? {};
const ALLOW_REMOTE = ENV.REPRO_ALLOW_REMOTE === '1';
const FIND_TIMEOUT_MS = 10_000;
/** Bounded, so a stuck step is reported as INCONCLUSIVE instead of a test timeout. */
const ACTION_TIMEOUT_MS = 10_000;
const NAVIGATION_TIMEOUT_MS = 30_000;
const WAIT_MS = Number(ENV.REPRO_WAIT_MS) > 0 ? Number(ENV.REPRO_WAIT_MS) : 30_000;
const SAFE_METHODS = new Set(['GET', 'HEAD', 'OPTIONS']);
/** Requests that stay open by design; the replay does not wait for them. */
const STREAMING = new Set(['eventsource', 'websocket']);
let IGNORE_PENDING: RegExp | undefined;
let SETUP_ERROR: string | undefined;
try {
  IGNORE_PENDING = ENV.REPRO_IGNORE_PENDING ? new RegExp(ENV.REPRO_IGNORE_PENDING) : undefined;
} catch {
  SETUP_ERROR = `REPRO_IGNORE_PENDING is not a valid regular expression: ${ENV.REPRO_IGNORE_PENDING}`;
}
const BASELINE_FILE = '.repro-baseline.json';

if (ENV.REPRO_STORAGE_STATE) test.use({ storageState: ENV.REPRO_STORAGE_STATE });

function isLocalHost(hostname: string): boolean {
  const h = hostname.toLowerCase();
  return (
    h === 'localhost' ||
    h.endsWith('.localhost') ||
    h === '127.0.0.1' ||
    h === '[::1]' ||
    h === '::1'
  );
}

/** Network URLs (http, https, ws, wss) count only when their host is local. */
function isLocalUrl(url: string): boolean {
  try {
    const u = new URL(url);
    const network = ['http:', 'https:', 'ws:', 'wss:'].includes(u.protocol);
    return !network || isLocalHost(u.hostname);
  } catch {
    return false;
  }
}

/** The origin to replay against and a rewrite of recorded URLs onto it. */
function target(): { origin: string; rewrite: (url: string) => string } {
  let origin = PLAN.recordedOrigin;
  if (ENV.BASE_URL) {
    const u = new URL(ENV.BASE_URL);
    if (u.protocol !== 'http:' && u.protocol !== 'https:') throw new Error('not http(s)');
    origin = u.origin;
  }
  return {
    origin,
    rewrite: (url) => {
      const u = new URL(url);
      if (u.origin !== PLAN.recordedOrigin) return url;
      return origin + u.pathname + u.search + u.hash;
    },
  };
}

// --- Baseline ----------------------------------------------------------------

interface FileSystem {
  readFileSync(path: string, encoding: 'utf8'): string;
  writeFileSync(path: string, data: string): void;
}

/** Node's fs, loaded without a static import so this file needs no Node typings. */
async function fileSystem(): Promise<FileSystem> {
  return (await import(['node', 'fs'].join(':'))) as FileSystem;
}

function baselinePath(): string {
  return `${test.info().file.replace(/[\\/][^\\/]*$/, '')}/${BASELINE_FILE}`;
}

interface Baseline {
  plan: string;
  runner: number;
  target: string;
  storageState: string;
  /** Indexes into PLAN.signals of the signals that some run reproduced. */
  reproduced: number[];
}

/** What a baseline must share with this run: plan, rules, server and sign-in state file. */
function baselineKey(origin: string): Omit<Baseline, 'reproduced'> {
  return { plan: PLAN.id, runner: RUNNER_VERSION, target: origin, storageState: ENV.REPRO_STORAGE_STATE ?? '' };
}

/** The signals earlier runs reproduced against this target (none when there is no baseline). */
async function readBaseline(origin: string): Promise<Set<number>> {
  try {
    const b = JSON.parse((await fileSystem()).readFileSync(baselinePath(), 'utf8')) as Baseline;
    const want = baselineKey(origin);
    const same =
      b.plan === want.plan &&
      b.runner === want.runner &&
      b.target === want.target &&
      (b.storageState ?? '') === want.storageState;
    return same && Array.isArray(b.reproduced) ? new Set(b.reproduced) : new Set();
  } catch {
    return new Set();
  }
}

/** Adds the signals this run reproduced to the baseline. */
async function writeBaseline(origin: string, reproduced: number[]): Promise<void> {
  const all = [...new Set([...(await readBaseline(origin)), ...reproduced])].sort((a, b) => a - b);
  const record = { ...baselineKey(origin), reproduced: all, at: new Date().toISOString() };
  try {
    (await fileSystem()).writeFileSync(baselinePath(), `${JSON.stringify(record, null, 2)}\n`);
  } catch {
    /* read-only folder: the next pass stays INCONCLUSIVE */
  }
}

// --- Finding elements --------------------------------------------------------

function cssString(value: string): string {
  return value.replace(/\\/g, '\\\\').replace(/"/g, '\\"').replace(/\n/g, '\\a ');
}

function locatorFor(page: Page, c: Candidate): Locator {
  switch (c.by) {
    case 'testid':
      return page.getByTestId(c.value);
    case 'css':
      return page.locator(`css=${c.value}`);
    case 'role':
      return page.getByRole(c.role as Parameters<Page['getByRole']>[0], {
        name: c.value,
        exact: true,
      });
    case 'label':
      return page.getByLabel(c.value, { exact: true });
    case 'name':
      return page.locator(`css=[name="${cssString(c.value)}"]`);
    case 'text':
      return page.getByText(c.value, { exact: true });
  }
}

/** The first candidate that matches exactly one element, waiting for the page. */
async function find(page: Page, t: Target): Promise<Locator> {
  const deadline = Date.now() + FIND_TIMEOUT_MS;
  for (;;) {
    for (const c of t.candidates) {
      const loc = locatorFor(page, c);
      if ((await loc.count().catch(() => 0)) === 1) return loc;
    }
    if (Date.now() > deadline) throw new Error(`no single element matches ${t.label}`);
    await page.waitForTimeout(200);
  }
}

// --- Replay ------------------------------------------------------------------

function describe(step: Step): string {
  switch (step.kind) {
    case 'goto':
      return `open ${step.url}`;
    case 'reload':
      return 'reload';
    case 'press':
      return `press ${step.key}`;
    default:
      return `${step.kind} ${step.target.label}`;
  }
}

async function run(page: Page, step: Step, rewrite: (url: string) => string): Promise<void> {
  switch (step.kind) {
    case 'goto': {
      const url = rewrite(step.url);
      if (!ALLOW_REMOTE && !isLocalUrl(url)) {
        throw new Error(`refused to open ${new URL(url).origin}, which is not a local address`);
      }
      await page.goto(url, { timeout: NAVIGATION_TIMEOUT_MS });
      return;
    }
    case 'reload':
      await page.reload({ timeout: NAVIGATION_TIMEOUT_MS });
      return;
    case 'press':
      await page.keyboard.press(step.key);
      return;
    case 'click':
      await (await find(page, step.target)).click({
        timeout: ACTION_TIMEOUT_MS,
        ...(step.button ? { button: step.button } : {}),
        ...(step.modifiers ? { modifiers: step.modifiers } : {}),
      });
      return;
    case 'fill': {
      const value = step.env !== undefined ? ENV[step.env] : step.value;
      if (value === undefined) {
        throw new Error(`set ${step.env} to the value for ${step.target.label} (it was redacted)`);
      }
      await (await find(page, step.target)).fill(value, { timeout: ACTION_TIMEOUT_MS });
      return;
    }
    case 'select':
      await (await find(page, step.target)).selectOption(step.value, { timeout: ACTION_TIMEOUT_MS });
      return;
    case 'upload': {
      if (step.file.startsWith('/') || step.file.split(/[\\/]/).includes('..')) {
        throw new Error(`upload path is not inside the export: ${step.file}`);
      }
      const dir = test.info().file.replace(/[\\/][^\\/]*$/, '');
      await (await find(page, step.target)).setInputFiles(`${dir}/${step.file}`, {
        timeout: ACTION_TIMEOUT_MS,
      });
      return;
    }
  }
}

// --- Observing ---------------------------------------------------------------

interface Seen {
  method: string;
  path: string;
  status: number | 'failed' | 'pending';
  /** Base content type of the response. */
  mime?: string;
  /** Index of the step that was running when the request started. */
  step: number;
  body: string | null;
  streaming: boolean;
}

function pathOf(url: string): string {
  try {
    return new URL(url).pathname;
  } catch {
    return url;
  }
}

/** Whether every recorded field is present with a value in the replayed body. */
function sentFields(body: string | null, fields: string[]): boolean {
  if (fields.length === 0) return true;
  if (!body) return false;
  let values: (key: string) => unknown;
  try {
    const obj = JSON.parse(body) as Record<string, unknown>;
    values = (k) => obj[k];
  } catch {
    const params = new URLSearchParams(body);
    values = (k) => params.get(k);
  }
  return fields.every((k) => {
    const v = values(k);
    return v !== undefined && v !== null && v !== '';
  });
}

function sameRequest(signal: Extract<Signal, { kind: 'request' }>, r: Seen): boolean {
  return r.method === signal.method && new RegExp(signal.pathPattern).test(r.path);
}

/** Each part found in order, after the previous one: no backtracking across parts. */
function partsMatch(parts: string[], text: string): boolean {
  let from = 0;
  for (const part of parts) {
    const re = new RegExp(part, 'g');
    re.lastIndex = from;
    const m = re.exec(text);
    if (!m) return false;
    from = m.index + m[0].length;
  }
  return true;
}

function succeeded(status: Seen['status']): boolean {
  return typeof status === 'number' && ((status >= 200 && status < 300) || status === 304);
}

/** The recorded failure again: the same status, not just any error (a 502 is not the recorded 500). */
function matches(signal: Signal, errors: string[], consoleErrors: string[], requests: Seen[]): boolean {
  if (signal.kind === 'request') {
    // Also the same kind of body: a dev-server proxy error is a 500 too.
    return requests.some(
      (r) =>
        sameRequest(signal, r) &&
        r.status === signal.status &&
        (signal.mime === undefined || r.mime === undefined || r.mime === signal.mime),
    );
  }
  return (signal.kind === 'exception' ? errors : consoleErrors).some((s) => partsMatch(signal.parts, s));
}

/**
 * The failing request was sent again after its step, with the recorded fields,
 * and succeeded (2xx or 304; a redirect such as one to a sign-in page is not).
 */
function reached(signal: Signal, requests: Seen[]): boolean {
  if (signal.kind !== 'request') return true;
  return requests.some(
    (r) =>
      sameRequest(signal, r) &&
      r.step >= signal.afterStep &&
      succeeded(r.status) &&
      sentFields(r.body, signal.fields),
  );
}

/** Why a failing request did not count as reached, when the replay sent it. */
function whyNotReached(signal: Extract<Signal, { kind: 'request' }>, requests: Seen[]): string | undefined {
  const sent = requests.filter((r) => sameRequest(signal, r) && r.step >= signal.afterStep);
  const other = sent.find((r) => r.status !== 'pending' && !succeeded(r.status));
  if (other) return `the replay's ${signal.method} ${signal.path} got ${other.status}, not the recorded ${signal.status} or a success`;
  return undefined;
}

function label(signal: Signal): string {
  return signal.kind === 'request'
    ? `${signal.method} ${signal.path} (recorded ${signal.status})`
    : `${signal.kind} "${signal.text}"`;
}

// --- Test --------------------------------------------------------------------

test(PLAN.title, async ({ page, context }) => {
  test.fixme(PLAN.fixme !== undefined, PLAN.fixme ?? '');
  // Room for every step to wait its full bound, so the verdict below still runs.
  test.setTimeout(
    NAVIGATION_TIMEOUT_MS +
      PLAN.steps.length * (NAVIGATION_TIMEOUT_MS + FIND_TIMEOUT_MS) +
      2 * WAIT_MS +
      PLAN.settleMs +
      10_000,
  );
  const outcome = (description: string) =>
    test.info().annotations.push({ type: 'repro-outcome', description });

  let stopped: string | undefined = SETUP_ERROR;
  let origin = PLAN.recordedOrigin;
  let rewrite = (url: string) => url;
  try {
    ({ origin, rewrite } = target());
  } catch {
    stopped = `BASE_URL must be an http(s) URL such as http://localhost:3000, not ${ENV.BASE_URL}`;
  }
  const errors: string[] = [];
  const consoleErrors: string[] = [];
  const seen = new Map<Request, Seen>();
  const blocked: string[] = [];
  let currentStep = 0;

  page.on('pageerror', (err) => errors.push(`${err.name}: ${err.message}`));
  page.on('console', (msg) => {
    if (msg.type() === 'error' || msg.type() === 'assert') consoleErrors.push(msg.text());
  });
  const leaked: string[] = [];
  // Redirect hops are not routed, so they cannot be blocked before they are
  // sent; they are reported for every page, popups included.
  context.on('request', (req) => {
    if (!ALLOW_REMOTE && req.redirectedFrom() !== null && !isLocalUrl(req.url())) {
      leaked.push(`${req.method()} ${new URL(req.url()).origin} (redirect)`);
    }
  });
  const watchSockets = (p: Page) =>
    p.on('websocket', (ws) => {
      if (!ALLOW_REMOTE && !isLocalUrl(ws.url())) leaked.push(`WebSocket ${new URL(ws.url()).origin}`);
    });
  watchSockets(page);
  context.on('page', watchSockets);
  page.on('request', (req) => {
    seen.set(req, {
      method: req.method(),
      path: pathOf(req.url()),
      status: 'pending',
      step: currentStep,
      body: req.postData(),
      streaming:
        STREAMING.has(req.resourceType()) || (IGNORE_PENDING?.test(pathOf(req.url())) ?? false),
    });
  });
  // Older Playwright versions have no WebSocket routing; the leak check above still reports them.
  const routeWebSocket = (context as { routeWebSocket?: typeof context.routeWebSocket }).routeWebSocket;
  if (typeof routeWebSocket === 'function') {
    await routeWebSocket.call(context, /.*/, (ws) => {
      if (!ALLOW_REMOTE && !isLocalUrl(ws.url())) {
        blocked.push(`WebSocket ${new URL(ws.url()).origin}`);
        void ws.close();
        return;
      }
      ws.connectToServer();
    });
  }
  page.on('response', (res) => {
    const s = seen.get(res.request());
    if (s) {
      s.status = res.status();
      s.mime = (res.headers()['content-type'] ?? '').split(';')[0]!.trim().toLowerCase() || undefined;
    }
  });
  page.on('requestfailed', (req) => {
    // An empty response the page never reads can be aborted after it arrived.
    const s = seen.get(req);
    if (s && s.status === 'pending') s.status = 'failed';
  });
  await context.route('**/*', async (route) => {
    const req = route.request();
    const u = new URL(req.url());
    const remote = (u.protocol === 'http:' || u.protocol === 'https:') && !isLocalHost(u.hostname);
    let topLevelNavigation = req.isNavigationRequest();
    try {
      topLevelNavigation &&= req.frame().parentFrame() === null;
    } catch {
      /* a popup's first navigation has no frame yet; it is top level */
    }
    if (!ALLOW_REMOTE && remote && (!SAFE_METHODS.has(req.method()) || topLevelNavigation)) {
      blocked.push(`${req.method()} ${u.origin}${u.pathname}`);
      seen.delete(req);
      await route.abort('blockedbyclient');
      return;
    }
    await route.fallback();
  });

  if (!stopped && !ALLOW_REMOTE && !isLocalUrl(origin)) {
    stopped = `${origin} is not a local address. Set BASE_URL to a local server, or REPRO_ALLOW_REMOTE=1 to replay against it.`;
  }
  for (const [i, step] of PLAN.steps.entries()) {
    if (stopped) break;
    currentStep = i;
    try {
      await test.step(`${i + 1}. ${describe(step)}`, () => run(page, step, rewrite));
    } catch (err) {
      const reason = err instanceof Error ? err.message.split('\n')[0] : String(err);
      stopped = `step ${i + 1} (${describe(step)}) did not run: ${reason}`;
    }
  }

  // Let the page finish: wait for its requests, then for the recorded delay,
  // and again if that delay started more requests. A request still pending at
  // the deadline makes the result INCONCLUSIVE, never a pass.
  const pending = () => [...seen.values()].filter((r) => r.status === 'pending' && !r.streaming);
  const deadline = Date.now() + WAIT_MS;
  let settled = false;
  while (!stopped && Date.now() < deadline) {
    while (pending().length > 0 && Date.now() < deadline) await page.waitForTimeout(100);
    if (pending().length > 0) break;
    if (settled) break;
    await page.waitForTimeout(PLAN.settleMs);
    settled = pending().length === 0;
  }
  const stillPending = stopped ? [] : pending();

  const requests = [...seen.values()];
  const again = PLAN.signals.filter((s) => matches(s, errors, consoleErrors, requests));
  if (again.length > 0) {
    outcome('REPRODUCED');
    await writeBaseline(origin, again.map((s) => PLAN.signals.indexOf(s)));
    throw new Error(`REPRODUCED: the recorded bug happened again:\n- ${again.map(label).join('\n- ')}`);
  }
  const reasons = [
    ...(stopped ? [stopped] : []),
    ...(stillPending.length > 0
      ? [
          `${stillPending.length} request(s) were still pending after ${WAIT_MS} ms: ${stillPending
            .slice(0, 3)
            .map((r) => `${r.method} ${r.path}`)
            .join(', ')}`,
        ]
      : []),
    ...PLAN.signals
      .filter((s) => !reached(s, requests))
      .map((s) =>
        s.kind !== 'request'
          ? `the replay never made ${label(s)}`
          : (whyNotReached(s, requests) ??
            (s.fields.length > 0
              ? `the replay did not send ${label(s)} again with ${s.fields.join(', ')} filled in`
              : `the replay never made ${label(s)} after step ${s.afterStep + 1}`)),
      ),
    ...(blocked.length > 0
      ? [`blocked ${blocked.length} request(s) to non-local hosts: ${blocked.slice(0, 3).join(', ')}`]
      : []),
    ...(leaked.length > 0
      ? [
          `reached non-local hosts through redirects or WebSockets, which cannot be blocked before they are sent: ${leaked
            .slice(0, 3)
            .join(', ')}`,
        ]
      : []),
    ...(test.info().retry > 0 ? ['this is a retry; a retry cannot report a fix (run without --retries)'] : []),
    ...PLAN.blockers,
  ];
  if (reasons.length === 0) {
    const baseline = await readBaseline(origin);
    const never = PLAN.signals.filter((_, i) => !baseline.has(i));
    if (baseline.size === 0) {
      reasons.push(
        `no earlier run of this test reproduced the bug against ${origin}. Run it on the unfixed code first; it records ${BASELINE_FILE} when it reproduces the bug.`,
      );
    } else if (never.length > 0) {
      reasons.push(
        `no earlier run reproduced ${never.map(label).join(', ')} against ${origin}, so its absence now shows nothing`,
      );
    }
  }
  if (reasons.length > 0) {
    outcome('INCONCLUSIVE');
    throw new Error(`INCONCLUSIVE: the replay cannot show whether the bug is gone:\n- ${reasons.join('\n- ')}`);
  }
  outcome('NOT REPRODUCED');
});
